    pspHubIntro: "각 페이지에는 실시간 수익률, DeFi Score 항목, 14일 모델 전망 범위, 이용 가능 여부와 주요 위험이 담겨 있어요. 숫자는 DefiLlama에서 오고, 점수와 전망은 모델 결과예요.",
