    tcpFaqHeading: "Preguntas frecuentes",
    tcpAnswer: (label, apyStr, project, chain, count, floorStr) =>
      `El mayor rendimiento honesto de ${label} ahora es ${apyStr} en ${project} (${chain}), entre ${count} ${(String(count) === '1' ? 'pool' : 'pools')} por encima del TVL mínimo de ${floorStr}. Las tasas son en vivo de DefiLlama y excluyen pools anómalos (APY >1000%).`,
    tcpFaqQ1: (label) => `¿Cuál es el mayor rendimiento de ${label} hoy?`,
