    tcpRateStabilityColRank: "Posición",
    tcpDepthHeading: "Cómo se ha comportado esta tasa",
    tcpDepthSpread: (symbol, poolCount, lowApyStr, highApyStr, chainCount) =>
      `${symbol} aparece en ${poolCount} ${(String(poolCount) === '1' ? 'pool' : 'pools')} aquí, con tasas de ${lowApyStr} a ${highApyStr} APY en ${chainCount} ${(String(chainCount) === '1' ? 'red' : 'redes')} — la tasa depende del protocolo y de la red que elijas, no solo del token.`,
    tcpDepthMean: (meanCount, poolCount, medianMeanStr) =>
      `${meanCount} de ${poolCount} ${(String(poolCount) === '1' ? 'pool' : 'pools')} ${(String(meanCount) === '1') ? 'tiene' : 'tienen'} un promedio de 30 días confiable registrado, con una mediana de ${medianMeanStr} — una buena referencia frente al número de hoy para saber si la tasa es estable o si hoy es solo un buen día.`,
    tcpDepthMixIncentives: (rewardCount, poolCount) =>
      `${rewardCount} de ${poolCount} ${(String(poolCount) === '1' ? 'pool' : 'pools')} ${(String(rewardCount) === '1') ? 'combina' : 'combinan'} APY de incentivos o de recompensas además de la tasa base. El rendimiento por incentivos se reduce con el tiempo, a medida que se agotan los programas de recompensas; la tasa base es el número más duradero.`,
    tcpDepthMixAllBase: (poolCount) =>
      (String(poolCount) === '1')
        ? 'El único pool paga una tasa base simple por ahora, sin APY de incentivos ni de recompensas mezclado.'
        : `Los ${poolCount} pools pagan una tasa base simple por ahora, sin APY de incentivos ni de recompensas mezclado.`,
    tcpDepthIlExposure: (ilCount, poolCount) =>
      `${ilCount} de ${poolCount} ${(String(poolCount) === '1' ? 'pool' : 'pools')} ${(String(ilCount) === '1') ? 'tiene' : 'tienen'} riesgo de pérdida impermanente, es decir, una posición con dos activos puede perder valor frente a simplemente mantener los activos, incluso mientras genera rendimiento.`,
    tcpDepthColMix: "Composición del rendimiento",
    tcpDepthMixBaseCell: "Tasa base",
    tcpDepthMixIncentiveCell: (shareStr) => `${shareStr} de incentivos`,
    tcpDepthNote: (floorStr) =>
      `El promedio de 30 días viene directo de DefiLlama y solo aparece cuando pasa el mismo filtro de sensatez que todos los demás números de esta página. Un guion significa que no pasó ese filtro, no que se esté ocultando. Todos los pools de aquí ya cumplen un TVL mínimo de ${floorStr}. Las tasas cambian a diario, así que tómalo como una foto del momento, no como una promesa.`,
